{"command":"$ErrorActionPreference='Continue'
function S($kw,$type){
  $u='http./'
  $r = curl.exe -sL --max-time 25 --compressed -A 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/131.0.0.0 Safari/537.36' -H 'Referer: http./' --proxy htt./ -G $u --data-urlencode "search_type=$type" --data-urlencode "keyword=$kw" 2>$null
  try{$j=$r|ConvertFrom-Json}catch{Write-Output "  <json fail>";return}
  Write-Output "=== [$type] $kw  num=$($j.data.numResults)"
  $n=0
  foreach($it in $j.data.result){
    if($n -ge 8){break}
    $n++
    $t=($it.title -replace '<[^>]+>','')
    $d=''
    if($it.pubdate){$d=[DateTimeOffset]::FromUnixTimeSeconds([int64]$it.pubdate).ToOffset([TimeSpan]::FromHours(8)).ToString('yyyy-MM-dd')}
    $extra=''
    if($it.bvid){$extra="bvid=$($it.bvid)"}
    if($it.id -and $type -eq 'article'){$extra="cv=$($it.id)"}
    $tag=$it.tag -replace '<[^>]+>',''
    Write-Output ("  {0} | {1} | {2} | tag={3}" -f $d,$t,$extra,$tag)
  }
}
S '原神 星扩散' 'video'
S '原神 星超导' 'video'
S '星扩散' 'article'
S '奥黛塔 星扩散' 'video'
S '甘雨 专武 7.4' 'video'","description":"压缩输出检索星扩散星超导与甘雨专武"}

