{"command":"$ErrorActionPreference='Continue'
function A($id,$max){
  $u="http./"
  $r = curl.exe -sL --max-time 30 --compressed -A 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/131.0.0.0 Safari/537.36' -H 'Referer: http./'$id --proxy htt./ $u 2>$null
  try{$j=($r -join '')|ConvertFrom-Json}catch{Write-Output "cv$id <json fail>";return}
  if($j.code -ne 0){Write-Output "cv$id code=$($j.code) msg=$($j.message)";return}
  $d=$j.data
  $pt=''; if($d.publish_time){$pt=[DateTimeOffset]::FromUnixTimeSeconds([int64]$d.publish_time).ToOffset([TimeSpan]::FromHours(8)).ToString('yyyy-MM-dd HH:mm')}
  Write-Output "===== cv$id | $($d.title) | $pt | author=$($d.author.name)"
  $t=$d.content
  $t=[regex]::Replace($t,'(?s)<(script|style).*?</\1>',' ')
  $t=[regex]::Replace($t,'(?s)<br\s*/?>',"`n")
  $t=[regex]::Replace($t,'(?s)</(p|div|h\d|li|tr)>',"`n")
  $t=[regex]::Replace($t,'<[^>]+>','')
  $t=[System.Net.WebUtility]::HtmlDecode($t)
  $t=[regex]::Replace($t,'[ \t]+',' ')
  $t=[regex]::Replace($t,'(\r?\n){3,}',"`n`n")
  if($t.Length -gt $max){$t=$t.Substring(0,$max)+"`n...[truncated total $($t.Length)]"}
  Write-Output $t
}
A 52974755 4200
A 53290428 1800","description":"抓取两篇星扩散机制文章正文"}

